97	uint8_t*
98	rtb_read_firmware(uint32_t *fw_len)
99	{
100	  struct stat st;
101	  int fd = -1;
102	  size_t fwsize;
103	  ssize_t result;
104	  uint8_t *fw_buf_temp = NULL;
105	
106	  if (!fw_len)
107	    {
108	      wlerr("%s: Invalid parameter", __func__);
109	      return NULL;
110	    }
111	
112	  if ((fd = open(PATCH_BIN_NAME, O_RDONLY)) < 0)
113	    {
114	      wlerr("Can't open firmware, %s", strerror(errno));
115	      return NULL;
116	    }
117	
118	  if (stat(PATCH_BIN_NAME, &st) < 0)
119	    {
120	      wlerr("Can't access firmware %s, %s", PATCH_BIN_NAME,
121	                  strerror(errno));
122	      close(fd);
123	      return NULL;
124	    }
125	
126	  fwsize = st.st_size;
127	  if (fwsize >= MAX_FW_SIZE)
128	    {
129	      wlerr("fw size(%d) is larger than max fw size(%d)", fwsize, MAX_FW_SIZE);
130	      close(fd);
131	      return NULL;
132	    }
133	
134	  fw_buf_temp = malloc(fwsize);
135	  if (!fw_buf_temp)
136	    {
137	      wlerr("Can't allocate memory for fw, %s", strerror(errno));
138	      close(fd);
139	      return NULL;
140	    }
141	
142	  result = read(fd, fw_buf_temp, fwsize);
143	  if (result != (ssize_t) fwsize)
144	    {
145	      wlerr("Read FW %s error, %s", PATCH_BIN_NAME, strerror(errno));
146	      free(fw_buf_temp);
147	      close(fd);
148	      return NULL;
149	    }
150	  *fw_len = (uint32_t)result;
151	
152	  close(fd);
153	  wlinfo("Load FW %s OK, size %zd", PATCH_BIN_NAME, result);
154	  return fw_buf_temp;
155	}
