455	int
456	rtkbt_board_fetch_command(uint8_t *command)
457	{
458	  unsigned int config_size = rtl_config_size;
459	  static unsigned int command_offset;
460	  int fragment_size = 0;
461	  uint8_t index;
462	
463	  if (command_offset >= config_size + rtl_fw_size)
464	    {
465	      return RTKHCI_COMMAND_DONE;
466	    }
467	
468	  if (command_offset < rtl_fw_size)
469	    {
470	      if (command_offset + RTKHCI_COMMAND_FRAGMENT_SIZE
471	          > rtl_fw_size)
472	        {
473	          fragment_size = rtl_fw_size - command_offset;
474	        }
475	
476	      else
477	        {
478	          fragment_size = RTKHCI_COMMAND_FRAGMENT_SIZE;
479	        }
480	
481	      memcpy (command + 5, rtl_fw + command_offset, fragment_size);
482	      command_offset += fragment_size;
483	    }
484	
485	  if (command_offset >= rtl_fw_size)
486	    {
487	      int config_offset = command_offset - rtl_fw_size;
488	      int config_len = config_size - config_offset;
489	      if (fragment_size < RTKHCI_COMMAND_FRAGMENT_SIZE)
490	        {
491	          int free = RTKHCI_COMMAND_FRAGMENT_SIZE - fragment_size;
492	          int copy_size;
493	          if (config_len > free)
494	            {
495	              copy_size = free;
496	            }
497	
498	          else
499	            {
500	              copy_size = config_len;
501	            }
502	
503	          memcpy (command + 5 + fragment_size,
504	                  rtl_config + config_offset, copy_size);
505	          command_offset += copy_size;
506	          fragment_size += copy_size;
507	        }
508	    }
509	
510	  index = (command_offset / RTKHCI_COMMAND_FRAGMENT_SIZE) - 1;
511	  if (command_offset % RTKHCI_COMMAND_FRAGMENT_SIZE > 0)
512	    {
513	      index++;
514	    }
515	
516	  // FIX ME ?
517	  if (index > 0x7f)
518	    {
519	      if (command_offset < (config_size + rtl_fw_size))
520	        {
521	          index = (index & 0x7f) + 0x01;
522	        }
523	      else
524	        {
525	          index = (index | 0x80) + 0x01;
526	        }
527	    }
528	  else
529	    {
530	        if (command_offset >= (config_size + rtl_fw_size))
531	        {
532	          index = index | 0x80;
533	        }
534	    }
535	
536	  command[3] = fragment_size + 1;
537	  command[4] = index;
538	  return RTKHCI_COMMAND_VALID;
539	}
