180	static bt_status_t callback_send_to_external(bt_instance_t* ins, bt_client_msg_t* msg)
181	{
182	    uv_mutex_lock(&ins->lock);
183	    if (!ins->external_async) {
184	        ins->external_async = malloc(sizeof(uv_async_t));
185	        int ret = uv_async_init(ins->external_loop, ins->external_async, bt_socket_client_async_cb);
186	        if (ret != 0) {
187	            uv_mutex_unlock(&ins->lock);
188	            return BT_STATUS_BUSY;
189	        }
190	        ins->external_async->data = ins;
191	    }
192	
193	    list_add_tail(&ins->msg_queue, &msg->node);
194	    uv_async_send(ins->external_async);
195	    uv_mutex_unlock(&ins->lock);
196	
197	    return BT_STATUS_SUCCESS;
