227	static int bt_socket_client_receive(uv_poll_t* poll, int fd, void* userdata)
228	{
229	    bt_instance_t* ins = userdata;
230	    bt_message_packet_t* packet;
231	    int ret;
232	
233	    packet = ins->packet;
234	
235	    ret = recv(fd, (char*)packet + ins->offset, sizeof(*packet) - ins->offset, 0);
236	    if (ret == 0) {
237	        thread_loop_remove_poll(poll);
238	        return ret;
239	    } else if (ret < 0) {
240	        if (errno == EINTR || errno == EAGAIN) {
241	            return BT_STATUS_SUCCESS;
242	        }
243	        return ret;
244	    }
245	
246	    ins->offset += ret;
247	
248	    if (ins->offset != sizeof(*packet)) {
249	        return BT_STATUS_SUCCESS;
250	    } else {
251	        ins->offset = 0;
252	    }
253	
254	    if (packet->code > BT_MESSAGE_START && packet->code < BT_MESSAGE_END) {
255	        if (ins->cpacket == NULL)
256	            return BT_STATUS_SUCCESS;
257	
258	        memcpy(ins->cpacket, packet, sizeof(*packet));
259	        uv_sem_post(&ins->message_processed);
260	        return BT_STATUS_SUCCESS;
261	    } else if (packet->code > BT_CALLBACK_START && packet->code < BT_CALLBACK_END) {
262	        bt_client_msg_t* msg = malloc(sizeof(*msg));
263	        if (!msg)
264	            return BT_STATUS_NOMEM;
265	
266	        msg->ins = ins;
267	        memcpy(&msg->packet, packet, sizeof(*packet));
268	        if (ins->external_loop) {
269	            bt_status_t status = callback_send_to_external(ins, msg);
270	            if (status != BT_STATUS_SUCCESS) {
271	                free(msg);
272	                return status;
273	            }
274	        } else {
275	            if (callback_send_to_queue_work(ins, msg) != BT_STATUS_SUCCESS) {
276	                free(msg);
277	                return BT_STATUS_FAIL;
278	            }
279	        }
280	    } else {
281	        assert(0);
282	    }
283	
284	    return BT_STATUS_SUCCESS;
285	}
