287	static void bt_socket_client_handle_event(uv_poll_t* poll, int status, int events)
288	{
289	    uv_os_fd_t fd;
290	    int ret;
291	    bt_instance_t* ins = poll->data;
292	
293	    ret = uv_fileno((uv_handle_t*)poll, &fd);
294	    if (ret) {
295	        thread_loop_remove_poll(poll);
296	        return;
297	    }
298	
299	    if (status != 0 || events & UV_DISCONNECT) {
300	        thread_loop_remove_poll(poll);
301	        if (ins && ins->disconnected) {
302	            BT_LOGE("%s socket disconnect, status = %d, events = %d", __func__, status, events);
303	            ins->disconnected(ins, NULL, status);
304	        }
305	    } else if (events & UV_READABLE) {
306	        ret = bt_socket_client_receive(poll, fd, poll->data);
307	        if (ret != BT_STATUS_SUCCESS)
308	            thread_loop_remove_poll(poll);
309	    }
310	}
