312	static int bt_socket_client_connect(int family, const char* name,
313	    const char* cpu, int port)
314	{
315	    union {
316	        struct sockaddr_in inet_addr;
317	        struct sockaddr_un local_addr;
318	#ifdef CONFIG_NET_RPMSG
319	        struct sockaddr_rpmsg rpmsg_addr;
320	#endif
321	    } u = { 0 };
322	    socklen_t addr_len = 0;
323	    int fd;
324	
325	    if (family == PF_LOCAL) {
326	        u.local_addr.sun_family = AF_LOCAL;
327	        snprintf(u.local_addr.sun_path, UNIX_PATH_MAX,
328	            BLUETOOTH_SOCKADDR_NAME, name);
329	        addr_len = sizeof(struct sockaddr_un);
330	    } else if (family == AF_INET) {
331	        u.inet_addr.sin_family = AF_INET;
332	#if defined(ANDROID)
333	        u.inet_addr.sin_addr.s_addr = htonl(CONFIG_INADDR_LOOPBACK);
334	#else
335	        u.inet_addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
336	#endif
337	        u.inet_addr.sin_port = htons(port);
338	        addr_len = sizeof(struct sockaddr_in);
339	    } else {
340	#ifdef CONFIG_NET_RPMSG
341	        u.rpmsg_addr.rp_family = AF_RPMSG;
342	        snprintf(u.rpmsg_addr.rp_name, RPMSG_SOCKET_NAME_SIZE,
343	            BLUETOOTH_SOCKADDR_NAME, name);
344	        if (cpu != NULL)
345	            strlcpy(u.rpmsg_addr.rp_cpu, cpu, sizeof(u.rpmsg_addr.rp_cpu));
346	        addr_len = sizeof(struct sockaddr_rpmsg);
347	#endif
348	    }
349	    if (!addr_len) {
350	        return -errno;
351	    }
352	
353	    fd = socket(family, SOCK_STREAM, 0);
354	    if (fd < 0)
355	        return -errno;
356	
357	    if (connect(fd, (struct sockaddr*)&u, addr_len) < 0) {
358	        close(fd);
359	        return -errno;
360	    }
361	
362	#ifdef CONFIG_NET_SOCKOPTS
363	    setSocketBuf(fd, SO_SNDBUF);
364	    setSocketBuf(fd, SO_RCVBUF);
365	#endif
366	
367	    return fd;
368	}
