374	int bt_socket_client_sendrecv(bt_instance_t* ins, bt_message_packet_t* packet,
375	    uint32_t code)
376	{
377	    uint8_t* send_data;
378	    int send_size;
379	    int ret;
380	
381	    BT_SOCKET_INS_VALID(ins, BT_STATUS_PARM_INVALID);
382	
383	    uv_mutex_lock(&ins->mutex);
384	
385	    packet->code = code;
386	
387	    ins->cpacket = packet;
388	
389	    send_data = (uint8_t*)packet;
390	    send_size = sizeof(*packet);
391	    while (send_size > 0) {
392	        ret = send(ins->peer_fd, send_data, send_size, 0);
393	        if (ret == 0) {
394	            break;
395	        } else if (ret < 0) {
396	            if (errno == EINTR || errno == EAGAIN)
397	                continue;
398	            break;
399	        }
400	        send_data += ret;
401	        send_size -= ret;
402	    }
403	
404	    if (ret <= 0) {
405	        uv_mutex_unlock(&ins->mutex);
406	        BT_LOGE("%s, bt socket send ret: %d error: %d", __func__, ret, errno);
407	        return BT_STATUS_FAIL;
408	    }
409	
410	    uv_sem_wait(&ins->message_processed);
411	
412	    ins->cpacket = NULL;
413	
414	    uv_mutex_unlock(&ins->mutex);
415	
416	    return BT_STATUS_SUCCESS;
417	}
