419	int bt_socket_client_init(bt_instance_t* ins, int family,
420	    const char* name, const char* cpu, int port)
421	{
422	    uv_poll_t* poll;
423	    int retry = CLIENT_MAX_RETRY;
424	
425	    ins->client_loop = zalloc(sizeof(uv_loop_t));
426	    if (!ins->client_loop)
427	        return BT_STATUS_NOMEM;
428	
429	    if (thread_loop_init(ins->client_loop) != 0) {
430	        free(ins->client_loop);
431	        ins->client_loop = NULL;
432	        return BT_STATUS_FAIL;
433	    }
434	
435	    ins->packet = malloc(sizeof(bt_message_packet_t));
436	    if (ins->packet == NULL) {
437	        bt_socket_client_deinit(ins);
438	        return BT_STATUS_NOMEM;
439	    }
440	
441	    ins->offset = 0;
442	    list_initialize(&ins->msg_queue);
443	    uv_mutex_init(&ins->lock);
444	
445	    uv_sem_init(&ins->message_processed, 0);
446	    uv_mutex_init(&ins->mutex);
447	    do {
448	        ins->peer_fd = bt_socket_client_connect(family, name, cpu, port);
449	        if (ins->peer_fd <= 0 && !retry) {
450	            /* connect fail, go out */
451	            bt_socket_client_deinit(ins);
452	            return BT_STATUS_PARM_INVALID;
453	        } else if (ins->peer_fd <= 0) {
454	            /* connect fail, retry after sleep 100ms */
455	            usleep(CLIENT_DELAY_MS(retry) * 1000);
456	            continue;
457	        } else {
458	            /* success, goto next step */
459	            break;
460	        }
461	    } while (retry--);
462	
463	    poll = thread_loop_poll_fd(ins->client_loop, ins->peer_fd, UV_READABLE | UV_DISCONNECT,
464	        bt_socket_client_handle_event, ins);
465	    if (poll == NULL) {
466	        bt_socket_client_deinit(ins);
467	        return BT_STATUS_PARM_INVALID;
468	    }
469	
470	    ins->poll = poll;
471	
472	    thread_loop_run(ins->client_loop, true, "bt_client");
473	
474	    return BT_STATUS_SUCCESS;
475	}
