495	void bt_socket_client_deinit(bt_instance_t* ins)
496	{
497	    uv_sem_destroy(&ins->message_processed);
498	    uv_mutex_destroy(&ins->mutex);
499	
500	    if (ins->packet)
501	        free(ins->packet);
502	
503	    if (!ins->poll)
504	        bt_socket_sync_close(ins);
505	    else
506	        do_in_thread_loop_sync(ins->client_loop, bt_socket_sync_close, ins);
507	
508	    if (ins->external_loop && ins->external_async) {
509	        struct list_node* node;
510	        struct list_node* tmp;
511	        uv_mutex_lock(&ins->lock);
512	        list_for_every_safe(&ins->msg_queue, node, tmp)
513	        {
514	            list_delete(node);
