516	        }
517	        uv_mutex_unlock(&ins->lock);
518	        uv_close((uv_handle_t*)ins->external_async, bt_socket_client_async_close);
519	    }
520	
521	    uv_mutex_destroy(&ins->lock);
522	    thread_loop_exit(ins->client_loop);
523	    free(ins->client_loop);
524	}
