569	static int bt_socket_async_client_handle_packet(bt_instance_t* ins, bt_message_packet_t* packet)
570	{
571	    bt_socket_async_client_t* priv = ins->priv;
572	
573	    if (packet->code > BT_MESSAGE_START && packet->code < BT_MESSAGE_END) {
574	        bt_message_context_t* ctx = (bt_message_context_t*)(uintptr_t)packet->context;
575	        bt_message_context_t* head = bt_list_node(bt_list_head(priv->pending_queue));
