581	
582	        bt_list_remove_node(priv->pending_queue, bt_list_head(priv->pending_queue));
583	    } else if (packet->code > BT_CALLBACK_START && packet->code < BT_CALLBACK_END) {
584	        bt_socket_client_callback_process(ins, packet, true);
585	    } else {
586	        assert(0);
587	    }
588	
