731	            uv_pipe_rpmsg_connect(&priv->conn_req, priv->pipe, rp_name, cpu, bt_socket_connect_cb);
732	        }
733	#endif
734	        else {
735	            return BT_STATUS_NOT_SUPPORTED;
736	        }
737	    }
738	
739	    ins->priv = priv;
