747	static void bt_socket_invoke_async_cb(bt_instance_t* ins, bt_list_t* list)
748	{
749	    bt_list_node_t* node;
750	
751	    for (node = bt_list_head(list); node != NULL; node = bt_list_next(list, node)) {
752	        bt_message_context_t* ctx = bt_list_node(node);
753	        if (ctx && ctx->reply_cb)
754	            ctx->reply_cb(ins, NULL, ctx->cb, ctx->userdata);
755	    }
756	}
