758	void bt_socket_async_client_deinit(bt_instance_t* ins)
759	{
760	    bt_socket_async_client_t* priv;
761	
762	    if (ins == NULL)
763	        return;
764	
765	    priv = ins->priv;
766	    if (priv == NULL)
767	        return;
768	
769	    uv_read_stop((uv_stream_t*)priv->pipe);
770	
771	    if (priv->pending_queue) {
772	        bt_socket_invoke_async_cb(ins, priv->pending_queue);
773	        bt_list_free(priv->pending_queue);
774	        priv->pending_queue = NULL;
