50	static bt_instance_impl_t* manager_find_instance(const char* name, pid_t pid)
51	{
52	    struct list_node* node;
53	
54	    uv_mutex_lock(&g_mutex);
55	
56	    list_for_every(&g_instances, node)
57	    {
58	        bt_instance_impl_t* ins = (bt_instance_impl_t*)node;
59	        size_t name_len = strlen(name);
60	        name_len = name_len > BT_INST_HOST_NAME_LEN ? BT_INST_HOST_NAME_LEN : name_len;
61	        if (strncmp((char*)ins->host_name, name, name_len) == 0 && ins->pid == pid) {
62	            uv_mutex_unlock(&g_mutex);
63	            return ins;
64	        }
65	    }
66	
67	    uv_mutex_unlock(&g_mutex);
68	
69	    return NULL;
70	}
