72	static bt_instance_impl_t* manager_find_instance_by_appid(uint32_t app_id)
73	{
74	    struct list_node* node;
75	
76	    uv_mutex_lock(&g_mutex);
77	
78	    list_for_every(&g_instances, node)
79	    {
80	        bt_instance_impl_t* ins = (bt_instance_impl_t*)node;
81	        if (ins->app_id == app_id) {
82	            uv_mutex_unlock(&g_mutex);
83	            return ins;
84	        }
85	    }
86	
87	    uv_mutex_unlock(&g_mutex);
88	
89	    return NULL;
90	}
