99	bt_status_t manager_create_instance(uint64_t handle, uint32_t type,
100	    const char* name, pid_t pid, uid_t uid,
101	    uint32_t* app_id)
102	{
103	    bt_instance_impl_t* ins = manager_find_instance(name, pid);
104	    if (ins)
105	        return BT_STATUS_FAIL;
106	
107	    uv_mutex_lock(&g_mutex);
108	
109	    if (g_instance_id == NULL)
110	        g_instance_id = index_allocator_create(10);
111	
112	    ins = malloc(sizeof(bt_instance_impl_t));
113	    if (!ins) {
114	        uv_mutex_unlock(&g_mutex);
115	        return BT_STATUS_NOMEM;
116	    }
117	
118	    ins->pid = pid;
119	    ins->uid = uid;
120	    int idx = index_alloc(g_instance_id);
121	    if (idx < 0) {
122	        free(ins);
123	        uv_mutex_unlock(&g_mutex);
124	        return BT_STATUS_NO_RESOURCES;
125	    }
126	    *app_id = idx;
127	    ins->app_id = idx;
128	    ins->handle = handle;
129	    ins->ins_type = type;
130	    snprintf((char*)ins->host_name, BT_INST_HOST_NAME_LEN, "%s", name);
131	
132	    list_add_tail(&g_instances, &ins->node);
133	
134	    uv_mutex_unlock(&g_mutex);
135	
136	    return BT_STATUS_SUCCESS;
137	}
