378	static int bt_socket_server_listen(int family, const char* name, int port)
379	{
380	    union {
381	        struct sockaddr_in inet_addr;
382	        struct sockaddr_un local_addr;
383	#ifdef CONFIG_NET_RPMSG
384	        struct sockaddr_rpmsg rpmsg_addr;
385	#endif
386	    } u = { 0 };
387	    int addr_len;
388	    int ret;
389	    int fd;
390	
391	    fd = socket(family, SOCK_STREAM | SOCK_NONBLOCK, 0);
392	    if (fd < 0)
393	        return -errno;
394	
395	    if (family == PF_LOCAL) {
396	        u.local_addr.sun_family = AF_LOCAL;
397	        snprintf(u.local_addr.sun_path, UNIX_PATH_MAX,
398	            BLUETOOTH_SOCKADDR_NAME, name);
399	        addr_len = sizeof(struct sockaddr_un);
400	    } else if (family == AF_INET) {
401	        u.inet_addr.sin_family = AF_INET;
402	        u.inet_addr.sin_addr.s_addr = htonl(INADDR_ANY);
403	        u.inet_addr.sin_port = htons(port);
404	        addr_len = sizeof(struct sockaddr_in);
405	#ifdef CONFIG_NET_RPMSG
406	    } else if (family == AF_RPMSG) {
407	        u.rpmsg_addr.rp_family = AF_RPMSG;
408	        snprintf(u.rpmsg_addr.rp_name, RPMSG_SOCKET_NAME_SIZE,
409	            BLUETOOTH_SOCKADDR_NAME, name);
410	        strcpy(u.rpmsg_addr.rp_cpu, "");
411	        addr_len = sizeof(struct sockaddr_rpmsg);
412	#endif
413	    } else {
414	        close(fd);
415	        return -EPFNOSUPPORT;
416	    }
417	
418	    ret = bind(fd, (struct sockaddr*)&u, addr_len);
419	    if (ret >= 0)
420	        ret = listen(fd, BLUETOOTH_SERVER_MAXCONN);
421	
422	    if (ret < 0) {
423	        close(fd);
424	        return -errno;
425	    }
426	
427	    return fd;
428	}
