434	int bt_socket_server_send(bt_instance_t* ins, bt_message_packet_t* packet,
435	    uint32_t code)
436	{
437	    bt_packet_cache_t* cache;
438	    int ret;
439	
440	    if (bt_socket_server_is_ins_detached(ins))
441	        return -1;
442	
443	    packet->code = code;
444	
445	    ret = bt_socket_server_trysend(ins);
446	    if (ret == 0) {
447	        ret = bt_socket_server_send_internal(ins, packet, sizeof(*packet), 0);
448	        if (ret < 0) {
449	            service_loop_remove_poll(ins->poll);
450	            ins->poll = NULL;
451	            return ret;
452	        }
453	    } else {
454	        ret = 0;
455	    }
456	
457	    if (ret != sizeof(*packet) && ins->poll) {
458	        cache = malloc(sizeof(*cache));
459	        if (cache == NULL)
460	            return BT_STATUS_NOMEM;
461	
462	        list_add_tail(&ins->msg_queue, &cache->node);
463	        memcpy(&cache->packet, packet, sizeof(*packet));
464	        cache->offset = ret;
465	
466	        service_loop_reset_poll(ins->poll, POLL_READABLE | POLL_WRITABLE);
467	    }
468	
469	    return 0;
470	}
