94	static void thread_message_callback(uv_async_t* handle)
95	{
96	    internel_msg_t* imsg;
97	    loop_priv_t* priv = handle->data;
98	
99	    for (;;) {
100	        uv_mutex_lock(&priv->msg_lock);
101	        imsg = (internel_msg_t*)list_remove_head(&priv->msg_queue);
102	        uv_mutex_unlock(&priv->msg_lock);
103	        if (!imsg)
104	            return;
105	
106	        imsg->func(imsg->msg);
107	        free(imsg);
108	    }
