187	 * Name: psock_local_connect
188	 *
189	 * Description:
190	 *   Find a local connection structure that is the appropriate "server"
191	 *   connection to be used with the provided "client" connection.
192	 *
193	 * Returned Value:
194	 *   Zero (OK) returned on success; A negated errno value is returned on a
195	 *   failure.  Possible failures include:
196	 *
197	 *   EISCONN - The specified socket is connection-mode and is already
198	 *     connected.
199	 *   EADDRNOTAVAIL - The specified address is not available from the
200	 *     local machine.
201	 *   ECONNREFUSED - The target address was not listening for connections or
202	 *     refused the connection request because the connection backlog has
203	 *     been exceeded.
204	 *
205	 ****************************************************************************/
206	
207	int psock_local_connect(FAR struct socket *psock,
208	                        FAR const struct sockaddr *addr)
209	{
210	  FAR struct local_conn_s *client = psock->s_conn;
211	  FAR struct sockaddr_un *unaddr = (FAR struct sockaddr_un *)addr;
212	  FAR const char *unpath = unaddr->sun_path;
213	  FAR struct local_conn_s *conn = NULL;
214	  uint8_t type = LOCAL_TYPE_PATHNAME;
215	  struct stat buf;
216	  int ret = OK;
217	
218	  if (client->lc_state == LOCAL_STATE_ACCEPT ||
219	      client->lc_state == LOCAL_STATE_CONNECTED)
220	    {
221	      return -EISCONN;
222	    }
223	
224	  if (unpath[0] == '\0')
225	    {
226	      type = LOCAL_TYPE_ABSTRACT;
227	      unpath++;
228	    }
229	
230	  /* Find the matching server connection */
231	
232	  local_lock();
233	  while ((conn = local_nextconn(conn)) != NULL)
234	    {
235	      /* Self found, continue */
236	
237	      if (conn == client)
238	        {
239	          continue;
240	        }
241	
242	      /* Handle according to the server connection type */
243	
244	      switch (conn->lc_type)
245	        {
246	        case LOCAL_TYPE_UNNAMED:   /* A Unix socket that is not bound to any name */
247	          break;
248	
249	        case LOCAL_TYPE_ABSTRACT:  /* lc_path is length zero */
250	        case LOCAL_TYPE_PATHNAME:  /* lc_path holds a null terminated string */
251	
252	          /* Anything in the listener list should be a stream socket in the
253	           * listening state
254	           */
255	
256	          if (conn->lc_state == LOCAL_STATE_LISTENING &&
257	              conn->lc_type == type && conn->lc_proto == SOCK_STREAM &&
258	              strncmp(conn->lc_path, unpath, UNIX_PATH_MAX - 1) == 0)
259	            {
260	              /* Bind the address and protocol */
261	
262	              client->lc_type  = conn->lc_type;
263	              client->lc_proto = conn->lc_proto;
264	              client->lc_instance_id = local_generate_instance_id();
265	
266	              /* The client is now bound to an address */
267	
268	              client->lc_state = LOCAL_STATE_BOUND;
269	
270	              /* We have to do more for the SOCK_STREAM family */
271	
272	              ret = local_stream_connect(client, conn,
273	                          _SS_ISNONBLOCK(client->lc_conn.s_flags));
274	
275	              local_unlock();
276	              return ret;
277	            }
278	
279	          break;
280	
281	        default:        /* Bad, memory must be corrupted */
282	          DEBUGPANIC(); /* PANIC if debug on */
283	          local_unlock();
284	          return -EINVAL;
285	        }
286	    }
287	
288	  local_unlock();
289	  ret = nx_stat(unpath, &buf, 1);
